import java.util.List;
import java.util.function.Function;

public class ReportTableTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static void checkCall(String label, Object expected, java.util.concurrent.Callable<Object> call) {
        Object actual;
        try {
            actual = call.call();
        } catch (Throwable t) {
            actual = t.getClass().getSimpleName();
        }
        check(label, expected, actual);
    }

    public static void main(String[] args) {
        check("widestOf(a, bbb, cc)", 3, ReportTable.widestOf(List.of("a", "bbb", "cc")));
        check("widestOf(empty)", 0, ReportTable.widestOf(new java.util.ArrayList<String>()));

        List<StockLine> items = List.of(new StockLine("Pen", 3), new StockLine("Notebook", 12));
        List<Function<StockLine, String>> columns = List.of(
                item -> item.name(),
                item -> String.valueOf(item.qty()));
        String expected = "Name     | Qty\n"
                + "Pen      | 3\n"
                + "Notebook | 12";
        check("two-column table", expected, ReportTable.render(items, List.of("Name", "Qty"), columns));

        List<Function<StockLine, String>> nameOnly = List.of(item -> item.name());
        check("a single column is never padded", "Name\nPen\nNotebook",
                ReportTable.render(items, List.of("Name"), nameOnly));

        List<Function<StockLine, String>> flipped = List.of(
                item -> String.valueOf(item.qty()),
                item -> item.name());
        check("a wide header widens its column", "Quantity | Item\n3        | Pen",
                ReportTable.render(List.of(new StockLine("Pen", 3)), List.of("Quantity", "Item"), flipped));

        List<Function<String, String>> wordColumns = List.of(
                word -> word,
                word -> String.valueOf(word.length()));
        check("any row type works", "Word   | Len\nfig    | 3\nbanana | 6",
                ReportTable.render(List.of("fig", "banana"), List.of("Word", "Len"), wordColumns));

        check("no rows means no output", "",
                ReportTable.render(new java.util.ArrayList<StockLine>(), List.of("Name", "Qty"), columns));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

