import java.util.ArrayList;
import java.util.List;
import java.util.function.Function;

/** Provided -- the row type the tests use. Do not edit. */
record StockLine(String name, int qty) { }

public class ReportTable {

    public static int widestOf(List<String> cells) {
        int widest = 0;
        for (String cell : cells) {
            if (cell.length() > widest) {
                widest = cell.length();
            }
        }
        return widest;
    }

    public static <T> String render(List<T> rows, List<String> headers, List<Function<T, String>> columns) {
        if (rows.isEmpty()) {
            return "";
        }
        List<List<String>> lines = new ArrayList<>();
        lines.add(new ArrayList<>(headers));
        for (T row : rows) {
            List<String> cells = new ArrayList<>();
            for (Function<T, String> column : columns) {
                cells.add(column.apply(row));
            }
            lines.add(cells);
        }

        int[] widths = new int[columns.size()];
        for (int c = 0; c < columns.size(); c++) {
            List<String> columnCells = new ArrayList<>();
            for (List<String> line : lines) {
                columnCells.add(line.get(c));
            }
            widths[c] = widestOf(columnCells);
        }

        StringBuilder out = new StringBuilder();
        for (int r = 0; r < lines.size(); r++) {
            if (r > 0) {
                out.append("\n");
            }
            List<String> line = lines.get(r);
            for (int c = 0; c < line.size(); c++) {
                if (c > 0) {
                    out.append(" | ");
                }
                String cell = line.get(c);
                if (c < line.size() - 1) {
                    while (cell.length() < widths[c]) {
                        cell = cell + " ";
                    }
                }
                out.append(cell);
            }
        }
        return out.toString();
    }
}
